const telegram = (()=>{const module={exports:{}};
'use strict';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function parseUpdate(update, adminId) {
  const base={update_id: Number.isSafeInteger(update?.update_id) && update.update_id>=0 ? update.update_id : null,ignored:true};
  const cb=update?.callback_query;
  const message=cb?.message||update?.message;
  const user=cb?.from||message?.from;
  if(!base.update_id || !adminId || String(user?.id)!==String(adminId) ||
     String(message?.chat?.id)!==String(adminId) || message?.chat?.type!=='private') return base;
  const result={...base,ignored:false,user_id:user.id,chat_id:message.chat.id,chat_type:'private',callback_id:cb?.id||null};
  if(cb) {
    const parts=String(cb.data||'').split(':');
    if(parts[0]==='f') return {...result,command:'find',args:parts[1]||'maps_demo'};
    if(!UUID.test(parts[1]||'')) return {...result,command:'help'};
    const command={a:'approve',r:'reject',d:'edit'}[parts[0]];
    const version=Number(parts[2]);
    if(!command || (command==='approve'&&(!Number.isInteger(version)||version<1))) return {...result,command:'help'};
    return {...result,command,lead_id:parts[1],version:command==='approve'?version:null};
  }
  const text=String(message.text||'').trim();
  if(text.length>3500) return {...result,command:'help'};
  const match=/^\/([a-z]+)(?:@[a-z0-9_]+)?(?:\s+([\s\S]*))?$/i.exec(text);
  if(!match) return {...result,command:'help'};
  const cmd=match[1].toLowerCase(),args=(match[2]||'').trim();
  if(['lead','draft','approve','reject'].includes(cmd)) {
    const [leadId,...rest]=args.split(/\s+/);
    if(!UUID.test(leadId||'')) return {...result,command:'help'};
    const version=rest[0]===undefined?null:Number(rest[0]);
    if(cmd==='approve' && (!Number.isSafeInteger(version)||version<1)) return {...result,command:'help'};
    return {...result,command:cmd,lead_id:leadId,version:cmd==='approve'?version:null,
      draft:cmd==='draft'?rest.join(' '):null};
  }
  const allowed=['start','today','find','leads','sources','stats','budget','stop','resume','threads','instagram','videos','source','stage','followup','jobs','chats','content','publish','cancel','media'];
  return {...result,command:allowed.includes(cmd)?cmd:'help',args};
}
module.exports={parseUpdate};

return module.exports;})();
const input=$input.first().json;return [{json:{command:telegram.parseUpdate(input.payload,input.admin_id),visitor:input.visitor}}];

const cards = (()=>{const module={exports:{}};
'use strict';
const escapeHtml = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function renderCard(lead) {
  const e = x => escapeHtml(String(x ?? '').slice(0, 500));
  const text = [
    lead.is_demo ? '🧪 <b>DEMO: вымышленный пример</b>' : '📋 <b>Лид — требуется проверка владельца</b>',
    `Компания: <b>${e(lead.company_name)}</b>`,
    `Город: ${e(lead.city)} · Ниша: ${e(lead.niche)}`,
    `Оценка: ${e(lead.score_0_100)}/100 · ${e(lead.classification)} · ${e(lead.scoring_method)}`,
    `Статус: ${e(lead.status)} · Сайт: ${e(lead.website_status)}`,
    `Основание: ${e(lead.proof_quote)}`,
    `Почему: ${e(lead.why_relevant)}`,
    `Оффер: ${e(lead.offer_type)}`,
    `Контакт: ${e(lead.public_contact || 'Не указан')}`,
    `Черновик (v${e(lead.draft_version || 1)}): ${e(lead.draft_message)}`,
    `ID: <code>${e(lead.lead_id || 'после сохранения')}</code>`,
    'КП не отправлено. Одобрение относится к ручной отправке.',
  ].join('\n');
  const rows = [];
  if (lead.lead_id) rows.push([
    { text: 'Одобрить', callback_data: `a:${lead.lead_id}:${lead.draft_version || 1}` },
    { text: 'Не беспокоить', callback_data: `r:${lead.lead_id}` },
  ], [{ text: 'Изменить черновик', callback_data: `d:${lead.lead_id}` }]);
  if (lead.source_url) rows.push([{ text: 'Открыть источник', url: lead.source_url }]);
  return { text, parse_mode: 'HTML', disable_web_page_preview: true, reply_markup: { inline_keyboard: rows } };
}
module.exports = { renderCard, escapeHtml };

return module.exports;})();

const r=$input.first().json.result;
const messages=r.ignored?[]:[...(r.text?[{text:cards.escapeHtml(r.text),parse_mode:'HTML',...(r.reply_markup?{reply_markup:r.reply_markup}:{})}]:[]),...(r.leads||[]).map(cards.renderCard)];
if(!r.ignored&&r.callback_id)messages.unshift({_method:'answerCallbackQuery',callback_query_id:r.callback_id,text:'Принято'});
return [{json:{update_id:r.update_id||null,messages,callback_id:r.callback_id||null}}];
